/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export interface RetrievedChunk {
  id: string
  /** The passage text as it was given to the model. */
  text: string
  /** Source document: a file name, path or title. A path keeps its basename when truncated. */
  source: string
  /** Opens the source document. */
  href?: string
  /** Page or section: "p. 4", "Refunds › Partial refunds". */
  location?: string
  /** Similarity from 0 to 1. */
  score: number
  tokens?: number
  /** The answer used or cited this chunk. */
  used?: boolean
  /** Position in the retriever's output, 1-based. Defaults to the array order. */
  rank?: number
}

export type RetrievedChunksSort = "rank" | "score"

export interface RetrievedChunksProps extends Omit<React.ComponentProps<"div">, "children" | "title"> {
  chunks: RetrievedChunk[]
  /** The search query. Its terms are highlighted in each chunk. */
  query?: string
  /** Terms to highlight instead of the ones found in `query`. */
  terms?: string[]
  /** Similarity cutoff. Chunks below it gray out, and in score order a line marks the cut. */
  threshold?: number
  sort?: RetrievedChunksSort
  defaultSort?: RetrievedChunksSort
  onSortChange?: (sort: RetrievedChunksSort) => void
  /** Retrieval in progress: skeleton chunks in the final layout. */
  loading?: boolean
  /** Retrieval failed. Say what happened and how to fix it. */
  error?: React.ReactNode
  onRetry?: () => void
  /** Header label. Default "Retrieved chunks". */
  title?: React.ReactNode
  /** Lines shown before a chunk collapses behind Show more. Default 3. */
  lineClamp?: number
  /** Makes each source a button, for example to open the document beside the chat. */
  onChunkSelect?: (chunk: RetrievedChunk) => void
  /** Shown when nothing was retrieved. */
  emptyState?: React.ReactNode
  /** Height of the scroll area. */
  maxHeight?: number | string
}

/* -------------------------------------------------------------------------------------------------
 * Highlighting
 * -----------------------------------------------------------------------------------------------*/

const STOPWORDS = new Set(
  "a an and are as at be by can do does for from has have how i if in is it of on or our that the this to was we what when where which who why will with you your".split(
    " ",
  ),
)

/** Content words from a query, longest first so overlapping terms prefer the longer match. */
export function queryTerms(query: string) {
  const words = query
    .toLowerCase()
    .split(/[^\p{L}\p{N}]+/u)
    .filter((w) => w.length > 2 && !STOPWORDS.has(w))
  return [...new Set(words)].sort((a, b) => b.length - a.length)
}

/**
 * The only shimmer in chatcn: a status label such as "Thinking". Static under reduced motion.
 * Pass `active={false}` to settle it into plain subtle text.
 */
function ShimmerText({
  active = true,
  className,
  ...props
}: React.ComponentProps<"span"> & { active?: boolean }) {
  return (
    <span
      data-slot="shimmer-text"
      className={cn("font-medium", active ? "chatcn-shimmer" : "text-(color:--chatcn-fg-subtle)", className)}
      {...props}
    />
  )
}

/* -------------------------------------------------------------------------------------------------
 * Formatting
 * -----------------------------------------------------------------------------------------------*/

const THIN = " "

/** Token count with thin-space grouping: 48 210. */
function formatTokenCount(n: number) {
  return Math.round(n)
    .toString()
    .replace(/\B(?=(\d{3})+(?!\d))/g, THIN)
}

function SortToggle({
  sort,
  onChange,
}: {
  sort: RetrievedChunksSort
  onChange: (sort: RetrievedChunksSort) => void
}) {
  const item = (value: RetrievedChunksSort, label: string) => (
    <button
      type="button"
      aria-pressed={sort === value}
      onClick={() => onChange(value)}
      className={cn(
        "chatcn-focus rounded-(--chatcn-radius-xs) text-[0.75rem]/[1rem] h-6 px-2 font-medium pointer-coarse:h-11",
        "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow] duration-150",
        sort === value
          ? "bg-(color:--chatcn-card) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xs)"
          : "text-(color:--chatcn-fg-subtle) hover:text-(color:--chatcn-fg)",
      )}
    >
      {label}
    </button>
  )
  return (
    // biome-ignore lint/a11y/useSemanticElements: a pair of toggle buttons, not a form fieldset
    <div
      role="group"
      aria-label="Sort chunks"
      className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-sm) flex shrink-0 items-center p-0.5"
    >
      {item("rank", "Rank")}
      {item("score", "Score")}
    </div>
  )
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

