function escapeRegExp(text: string) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
}

/**
 * Splits text into plain and matched runs. Terms match at the start of a word and run to its end,
 * so "refund" also lights up "refunds" and "refunded".
 */
function highlight(text: string, terms: string[]) {
  if (terms.length === 0) return [{ text, match: false }]
  const pattern = new RegExp(
    `(?<![\\p{L}\\p{N}])(?:${terms.map(escapeRegExp).join("|")})[\\p{L}\\p{N}]*`,
    "giu",
  )
  const out: { text: string; match: boolean }[] = []
  let last = 0
  for (const m of text.matchAll(pattern)) {
    const at = m.index ?? 0
    if (at > last) out.push({ text: text.slice(last, at), match: false })
    out.push({ text: m[0], match: true })
    last = at + m[0].length
  }
  if (last < text.length) out.push({ text: text.slice(last), match: false })
  return out
}

function ChunkText({
  text,
  terms,
  below,
  lineClamp,
}: {
  text: string
  terms: string[]
  below: boolean
  lineClamp: number
}) {
  const ref = React.useRef<HTMLParagraphElement>(null)
  const [open, setOpen] = React.useState(false)
  const [overflows, setOverflows] = React.useState(false)
  const id = React.useId()
  const parts = React.useMemo(() => highlight(text, terms), [text, terms])

  // Measure against the clamp, not a character count, so the toggle shows exactly when needed.
  React.useLayoutEffect(() => {
    const el = ref.current
    if (!el || open) return
    const measure = () => setOverflows(el.scrollHeight > el.clientHeight + 1)
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(el)
    return () => observer.disconnect()
  }, [open, text])

  return (
    <div className="flex flex-col items-start gap-1">
      <p
        ref={ref}
        id={id}
        dir="auto"
        className={cn(
          "text-[0.8125rem]/[1.25rem] leading-[1.55] text-pretty [overflow-wrap:anywhere] whitespace-pre-line",
          below ? "text-(color:--chatcn-fg-subtle)" : "text-(color:--chatcn-fg-muted)",
        )}
        style={
          open
            ? undefined
            : {
                display: "-webkit-box",
                WebkitBoxOrient: "vertical",
                WebkitLineClamp: lineClamp,
                overflow: "hidden",
              }
        }
      >
        {parts.map((part, i) =>
          part.match ? (
            <mark
              key={i}
              data-slot="retrieved-chunks-match"
              // Matched words step up to ink over a soft underline: the reason the chunk matched
              // reads at a glance, without boxes breaking the sentence apart.
              className={cn(
                "bg-transparent underline decoration-2 underline-offset-[3px] [text-decoration-skip-ink:none]",
                below
                  ? "text-(color:--chatcn-fg-muted) decoration-(color:--chatcn-border)"
                  : "text-(color:--chatcn-fg) decoration-(color:--chatcn-border-strong)",
              )}
            >
              {part.text}
            </mark>
          ) : (
            <React.Fragment key={i}>{part.text}</React.Fragment>
          ),
        )}
      </p>
      {overflows || open ? (
        <button
          type="button"
          aria-expanded={open}
          aria-controls={id}
          onClick={() => setOpen((v) => !v)}
          className={cn(
            "chatcn-focus rounded-(--chatcn-radius-xs) text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) -mx-1 h-6 px-1 font-medium",
            "hover:text-(color:--chatcn-fg) ease-(--chatcn-ease-standard) transition-colors duration-150 pointer-coarse:h-11",
          )}
        >
          {open ? "Show less" : "Show more"}
        </button>
      ) : null}
    </div>
  )
}

/* -------------------------------------------------------------------------------------------------
 * RetrievedChunks
 * -----------------------------------------------------------------------------------------------*/

/**
 * What the retriever handed the model, for debugging RAG: each passage with its source and page,
 * similarity as a bar and a figure, the query terms it matched, its token count and whether the
 * answer used it. A cutoff grays out weak matches and, in score order, draws the line between them.
 */
export function RetrievedChunks({
  chunks,
  query,
  terms: termsProp,
  threshold,
  sort: sortProp,
  defaultSort = "score",
  onSortChange,
  loading = false,
  error,
  onRetry,
  title = "Retrieved chunks",
  lineClamp = 3,
  onChunkSelect,
  emptyState,
  maxHeight,
  className,
  ...props
}: RetrievedChunksProps) {
  const [sortState, setSortState] = React.useState(defaultSort)
  const sort = sortProp ?? sortState
  const setSort = (next: RetrievedChunksSort) => {
    if (sortProp === undefined) setSortState(next)
    onSortChange?.(next)
  }

  const terms = React.useMemo(
    () =>
      termsProp
        ? [...new Set(termsProp.map((t) => t.toLowerCase()).filter(Boolean))].sort(
            (a, b) => b.length - a.length,
          )
        : query
          ? queryTerms(query)
          : [],
    [termsProp, query],
  )

  const ranked = React.useMemo(() => {
    const list = chunks.map((chunk, i) => ({ chunk, rank: chunk.rank ?? i + 1 }))
    if (sort === "score") list.sort((a, b) => b.chunk.score - a.chunk.score || a.rank - b.rank)
    else list.sort((a, b) => a.rank - b.rank)
    return list
  }, [chunks, sort])

  const isBelow = (chunk: RetrievedChunk) => threshold !== undefined && chunk.score < threshold
  const belowCount = chunks.filter(isBelow).length
  const tokenTotal = chunks.reduce((sum, c) => sum + (c.tokens ?? 0), 0)
  const usedCount = chunks.filter((c) => c.used).length
  // In score order everything under the cutoff is contiguous, so one line can mark it.
  const cutAt =
    sort === "score" && threshold !== undefined && belowCount > 0
      ? ranked.findIndex(({ chunk }) => isBelow(chunk))
      : -1

  const state = loading ? "loading" : error ? "error" : chunks.length === 0 ? "empty" : "done"

  return (
    <div
      data-slot="retrieved-chunks"
      data-chunks-state={state}
      aria-busy={loading || undefined}
      className={cn(
        "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) text-(color:--chatcn-fg) @container flex min-w-0 flex-col overflow-hidden",
        "forced-colors:outline-1 forced-colors:outline-solid",
        className,
      )}
      {...props}
    >
      <div
        data-slot="retrieved-chunks-header"
        className="border-(color:--chatcn-border)/70 flex min-h-11 flex-wrap items-center gap-x-3 gap-y-1 border-b py-2 ps-4 pe-2"
      >
        <div className="flex min-w-0 flex-1 flex-col">
          <h3 className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] font-medium">{title}</h3>
          {query ? (
            <p dir="auto" className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) truncate text-start">
              <span className="sr-only">Query: </span>
              {`“${query}”`}
            </p>
          ) : null}
        </div>
        {loading ? (
          <ShimmerText className="text-[0.8125rem]/[1.25rem] pe-2">Retrieving</ShimmerText>
        ) : chunks.length > 0 ? (
          <>
            <p dir="auto" className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
              {`${chunks.length} ${chunks.length === 1 ? "chunk" : "chunks"}`}
              {tokenTotal > 0 ? `, ${formatTokenCount(tokenTotal)} tokens` : ""}
              {`, ${usedCount} used`}
            </p>
            <SortToggle sort={sort} onChange={setSort} />
          </>
        ) : null}
      </div>

      {error ? (
        <div role="alert" className="flex flex-col items-center gap-2 px-6 py-9 text-center">
          <CircleXIcon aria-hidden="true" className="text-(color:--chatcn-red) size-5" />
          <div className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) max-w-sm text-pretty">{error}</div>
          {onRetry ? (
            <Button
              size="sm"
              variant="outline"
              onClick={onRetry}
              className="mt-1 pointer-coarse:h-11"
            >
              <RotateCcwIcon />
              Retry search
            </Button>
          ) : null}
        </div>
      ) : loading ? (
        <ul aria-label="Loading chunks" className="flex flex-col">
          {[0, 1, 2].map((i) => (
            <ChunkSkeleton key={i} index={i} />
          ))}
        </ul>
      ) : chunks.length === 0 ? (
        <div className="flex flex-col items-center gap-1.5 px-6 py-10 text-center">
          {emptyState ?? (
            <>
              <SearchXIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) mb-1 size-6" />
              <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) font-medium">No passages matched</p>
              <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) max-w-sm text-pretty">
                Lower the similarity cutoff or rephrase the query, and check that the documents
                finished indexing.
              </p>
            </>
          )}
        </div>
      ) : (
        <div style={{ maxHeight }} className="chatcn-scroll min-h-0 overflow-auto">
          <ol aria-label="Chunks" className="flex flex-col">
            {ranked.map(({ chunk, rank }, i) => {
              const below = isBelow(chunk)
              return (
                <React.Fragment key={chunk.id}>
                  {i === cutAt ? (
                    <li
                      data-slot="retrieved-chunks-cutoff"
                      className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex items-center gap-2.5 px-4 pt-3 pb-1 tabular-nums"
                    >
                      <span className="shrink-0">{`Cutoff ${threshold?.toFixed(2)}`}</span>
                      <hr
                        aria-label={`Similarity cutoff ${threshold?.toFixed(2)}`}
                        className="border-(color:--chatcn-border-strong) m-0 h-0 flex-1 border-0 border-t border-dashed"
                      />
                      <span className="shrink-0">{`${belowCount} below`}</span>
                    </li>
                  ) : null}
                  <li
                    data-slot="retrieved-chunk"
                    data-below-threshold={below ? "" : undefined}
                    data-used={chunk.used ? "" : undefined}
                    className={cn(
                      "flex flex-col gap-1.5 py-3 ps-4 pe-4",
                      "border-(color:--chatcn-border)/70 border-b last:border-b-0",
                      i === cutAt - 1 && "border-b-0",
                    )}
                  >
                    <div className="text-[0.8125rem]/[1.25rem] flex min-w-0 items-center gap-2.5">
                      <span
                        className={cn(
                          "text-[0.75rem]/[1rem] w-3 shrink-0 text-end tabular-nums",
                          below ? "text-(color:--chatcn-fg-faint)" : "text-(color:--chatcn-fg-subtle)",
                        )}
                      >
                        <span className="sr-only">Rank </span>
                        {rank}
                      </span>
                      <div
                        className={cn(
                          "flex min-w-0 flex-1 items-center gap-1.5",
                          below ? "text-(color:--chatcn-fg-muted)" : "text-(color:--chatcn-fg)",
                        )}
                      >
                        <FileTextIcon
                          aria-hidden="true"
                          className="text-(color:--chatcn-fg-subtle) size-3.5 shrink-0"
                        />
                        {chunk.href || onChunkSelect ? (
                          (() => {
                            const linkClass = cn(
                              "chatcn-focus rounded-(--chatcn-radius-xs) -mx-0.5 flex min-w-0 px-0.5",
                              "hover:decoration-(color:--chatcn-border-strong) underline-offset-2 hover:underline",
                            )
                            return chunk.href ? (
                              <a
                                href={chunk.href}
                                className={linkClass}
                                onClick={
                                  onChunkSelect
                                    ? (event) => {
                                        event.preventDefault()
                                        onChunkSelect(chunk)
                                      }
                                    : undefined
                                }
                              >
                                <SourceLabel source={chunk.source} />
                              </a>
                            ) : (
                              <button
                                type="button"
                                className={cn(linkClass, "text-start")}
                                onClick={() => onChunkSelect?.(chunk)}
                              >
                                <SourceLabel source={chunk.source} />
                              </button>
                            )
                          })()
                        ) : (
                          <SourceLabel source={chunk.source} />
                        )}
                        {chunk.location ? (
                          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) min-w-0 shrink-[2] truncate">
                            {chunk.location}
                          </span>
                        ) : null}
                      </div>
                      <div className="text-[0.75rem]/[1rem] flex shrink-0 items-center gap-3">
                        {chunk.used ? (
                          <span
                            data-slot="retrieved-chunks-used"
                            className="text-(color:--chatcn-fg) inline-flex items-center gap-1 font-medium"
                          >
                            <CheckIcon aria-hidden="true" className="size-3" strokeWidth={2} />
                            Used
                          </span>
                        ) : (
                          <span className="sr-only">Not used</span>
                        )}
                        {chunk.tokens !== undefined ? (
                          <span
                            dir="ltr"
                            className="text-(color:--chatcn-fg-subtle) tabular-nums @max-[24rem]:hidden"
                          >
                            {`${formatTokenCount(chunk.tokens)} tok`}
                          </span>
                        ) : null}
                        <span className="sr-only">Similarity </span>
                        <ScoreBar score={chunk.score} threshold={threshold} below={below} />
                      </div>
                    </div>
                    <div className="ps-[1.375rem]">
                      <ChunkText
                        text={chunk.text}
                        terms={terms}
                        below={below}
                        lineClamp={lineClamp}
                      />
                    </div>
                    {below && sort === "rank" ? (
                      <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) ps-[1.375rem]">
                        Below the cutoff
                      </span>
                    ) : null}
                  </li>
                </React.Fragment>
              )
            })}
          </ol>
        </div>
      )}
    </div>
  )
}

